<?php
require __DIR__.'/config.php';require_role(['admin']);$events=read_json('timetable');
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$a=$_POST['action']??'';
if($a==='add'){collection_post('timetable');flash('Timetable entry added.');}
if($a==='delete'){collection_delete('timetable',(int)$_POST['id']);flash('Timetable entry removed.');}
redirect('timetable.php');}
$days=['Monday','Tuesday','Wednesday','Thursday','Friday'];$by=[];foreach($events as $e)$by[$e['day']??''][]=$e;
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Timetable Builder</title><link rel="stylesheet" href="cms.css"><style>.wrap{max-width:1200px;margin:auto;padding:28px}.grid{display:grid;grid-template-columns:repeat(5,1fr);gap:12px}.card{border:1px solid #dde3dd;border-radius:14px;padding:16px;background:#fff}.entry{padding:10px;border:1px solid #ddd;border-radius:9px;margin:8px 0}input,select{width:100%;box-sizing:border-box;margin:5px 0 10px}@media(max-width:900px){.grid{grid-template-columns:1fr}}</style><link rel="stylesheet" href="assets/dynamic-site.css">
</head><body class="rf-dynamic"><div class="wrap"><p><a href="index.php">← Dashboard</a></p><h1>Timetable Builder</h1><div class="card"><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="add"><div class="grid" style="grid-template-columns:repeat(4,1fr)"><label>Day<select name="day"><?php foreach($days as $d):?><option><?=$d?></option><?php endforeach;?></select></label><label>Time<input name="time" placeholder="08:00–08:45" required></label><label>Subject<input name="subject" required></label><label>Teacher / Room<input name="teacher" placeholder="Teacher or room"></label></div><button>Add to timetable</button></form></div><div class="grid" style="margin-top:18px"><?php foreach($days as $d):?><section class="card"><h2><?=h($d)?></h2><?php foreach($by[$d]??[] as $e):?><div class="entry"><strong><?=h($e['time']??'')?></strong><br><?=h($e['subject']??'')?><small><br><?=h($e['teacher']??'')?></small><form method="post" style="margin-top:7px"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$e['id']?>"><button>Remove</button></form></div><?php endforeach;if(empty($by[$d])):?><p>No classes.</p><?php endif;?></section><?php endforeach;?></div></div><script src="assets/dynamic-site.js"></script>
